//! Apple Cassette Interface (ACI) tape format: encoder, renderer, edge
//! detector, decoder and virtual tape player.
//!
//! # Format (as produced by the ACI ROM, Wozniak 1976)
//!
//! All timing is generated by software, by toggling the ACI output
//! flip-flop (any access to `$C000-$C0FF`). The encoder in this module does
//! not approximate this: [`rom_write_toggles`] runs the *original ACI ROM
//! WRITE routine* on an emulated 6502 and records the cycle at which every
//! toggle happens, so the exported audio is what a real Apple-1 would put on
//! tape (with the clock model of [`Timing`]).
//!
//! * header: ~10 s of "1" cycles (~1 kHz, slightly asymmetric phases),
//! * start bit: one short half period followed by a "0" half period,
//! * data: each byte MSB first, one full cycle per bit,
//!   "0" ≈ 2 kHz (≈ 2 x 250 µs), "1" ≈ 1 kHz (≈ 2 x 500 µs),
//! * no checksum, no length, no address: the reader must give the range.
//!
//! See `README.md` for the measured values.

use crate::cpu::{Cpu, FLAG_I, FLAG_U};
use crate::machine::{Board, Config};
use crate::roms::aci;
use crate::timing::Timing;

/// Run the ACI ROM WRITE routine and return the time (seconds, from the start
/// of the run) of every toggle of the output flip-flop.
///
/// Each segment is written exactly like `start.endW` (header + data). Several
/// segments behave like `A.BW C.DW`.
///
/// The data is placed at a relocated address with the same low byte, so the
/// cycle timing (which depends on page crossings of the pointer) is identical
/// to writing from the original address.
/// Text of an ACI range `S.E` as it must be typed on the real Apple-1.
///
/// The ACI ROM parser does NOT clear its hex accumulator at the '.'
/// separator (SEP at $C166 only copies HEX1 to HEX2, see the listing in the
/// Mimeo guide, appendix D): the end address is `(start << 4*digits) | end`
/// truncated to 16 bits. `4A.FF` therefore means $004A..$4AFF! The end is
/// printed with 4 digits, which always shifts the start out completely
/// (Star Trek: `004A.00FF 0300.0FFF`); the start too, for readability.
pub fn aci_range_text(start: u16, end: u16) -> String {
    format!("{start:04X}.{end:04X}")
}

/// What the ACI parser makes of `S.E` typed with the given digits (used to
/// check user-typed ranges).
pub fn aci_parse_range(text: &str) -> Option<(u16, u16)> {
    let mut acc: u32 = 0;
    let mut start = None;
    for c in text.trim().trim_end_matches(['R', 'W', 'r', 'w']).chars() {
        if c == '.' {
            start = Some(acc as u16);
        } else {
            acc = ((acc << 4) | c.to_digit(16)?) & 0xFFFF;
        }
    }
    Some((start?, acc as u16))
}

pub fn rom_write_toggles(segments: &[(u16, &[u8])], timing: Timing) -> Result<Vec<f64>, String> {
    let cfg = Config { aci: true, display_throttle: false, timing, ..Config::default() };
    let mut board = Board::new(cfg);
    board.all_ram();
    let mut cpu = Cpu::new();
    board.recording = Some(Vec::new());
    // The whole command line "S.EW S.EW ..." is put in the input buffer and
    // parsed by the ROM itself, exactly as if it had been typed: the header
    // length depends on X (index of each 'W', first inner loop of WHEADER)
    // and the gap between two records includes the parsing of the next
    // range. Ranges are written as `aci_range_text` prints them (e.g.
    // "004A.00FFW 0300.0FFFW"). When the ROM reaches WRITE, the data of the
    // current segment is placed at a relocated address with the same low
    // byte (identical cycle timing) and HEX1/HEX2 are pointed at it.
    let mut line = String::new();
    for (n, &(start, data)) in segments.iter().enumerate() {
        if data.is_empty() {
            return Err("segment vide".into());
        }
        let end_addr = start as u32 + data.len() as u32 - 1;
        if end_addr > 0xFFFF {
            return Err("segment au-delà de $FFFF".into());
        }
        let base = 0x0300u32 | (start as u32 & 0x00FF);
        if base + data.len() as u32 - 1 > 0xBFFF {
            return Err(format!("segment trop long ({} octets, max {})", data.len(), 0xBFFF - base + 1));
        }
        if n > 0 {
            line.push(' ');
        }
        line.push_str(&aci_range_text(start, end_addr as u16));
        line.push('W');
    }
    if line.len() > 127 {
        return Err("trop de plages pour une seule ligne de commande".into());
    }
    for (i, c) in line.bytes().enumerate() {
        board.mem[0x0200 + i] = c | 0x80;
    }
    board.mem[0x0200 + line.len()] = 0x8D;
    cpu.pc = 0xC123; // LDX #-1 / NEXTCMD: parse the line just typed
    cpu.sp = 0xFF;
    cpu.p = FLAG_U | FLAG_I;
    let total: u64 = segments.iter().map(|s| s.1.len() as u64).sum();
    let limit = board.cycles + 40_000_000 * segments.len() as u64 + total * 2_000;
    let mut n = 0usize;
    while cpu.pc != 0xC163 {
        if cpu.pc == aci::WRITE {
            let (start, data) = *segments.get(n).ok_or("analyse de ligne inattendue")?;
            let base = 0x0300u16 | (start & 0x00FF);
            let end = base + data.len() as u16 - 1;
            board.mem[base as usize..=end as usize].copy_from_slice(data);
            board.mem[aci::HEX2L as usize] = base as u8;
            board.mem[aci::HEX2H as usize] = (base >> 8) as u8;
            board.mem[aci::HEX1L as usize] = end as u8;
            board.mem[aci::HEX1H as usize] = (end >> 8) as u8;
            n += 1;
        }
        cpu.step(&mut board);
        if board.cycles > limit {
            return Err("la routine ACI ne s'est pas terminee".into());
        }
    }
    if n != segments.len() {
        return Err("la ligne de commande ACI n'a pas été analysée comme prévu".into());
    }
    let rec = board.recording.take().unwrap_or_default();
    Ok(rec.into_iter().map(|c| timing.cycles_to_secs(c)).collect())
}

/// Options for turning toggle times into audio.
#[derive(Debug, Clone, Copy)]
pub struct RenderOptions {
    pub sample_rate: u32,
    pub amplitude: f32,
    /// Silence before the first edge (s).
    pub lead_silence: f64,
    /// Silence after the last edge (s).
    pub tail_silence: f64,
}

impl Default for RenderOptions {
    fn default() -> Self {
        RenderOptions { sample_rate: 44100, amplitude: 0.7, lead_silence: 0.5, tail_silence: 0.5 }
    }
}

/// Render a square wave whose edges are at the given times. Each output
/// sample is the exact average of the signal over the sample period (box
/// filter), so edge positions are preserved with sub-sample accuracy.
pub fn render_toggles(toggles: &[f64], o: &RenderOptions) -> Vec<f32> {
    if toggles.is_empty() {
        return vec![0.0; (o.sample_rate as f64 * (o.lead_silence + o.tail_silence)) as usize];
    }
    let t0 = toggles[0];
    let a = o.amplitude as f64;
    // change points (time, level after)
    let mut pts: Vec<(f64, f64)> = Vec::with_capacity(toggles.len() + 1);
    for (i, &t) in toggles.iter().enumerate() {
        let lvl = if i % 2 == 0 { a } else { -a };
        pts.push((t - t0 + o.lead_silence, lvl));
    }
    let last = pts.last().unwrap().0;
    pts.push((last + 0.0005, 0.0));
    let total = last + 0.0005 + o.tail_silence;
    let rate = o.sample_rate as f64;
    let n = (total * rate).ceil() as usize;
    let dt = 1.0 / rate;
    let mut out = Vec::with_capacity(n);
    let mut idx = 0usize; // first change point with time > window start
    let mut level = 0.0f64; // level at window start
    for s in 0..n {
        let w0 = s as f64 * dt;
        let w1 = w0 + dt;
        while idx < pts.len() && pts[idx].0 <= w0 {
            level = pts[idx].1;
            idx += 1;
        }
        let mut acc = 0.0;
        let mut cur_t = w0;
        let mut cur_l = level;
        let mut j = idx;
        while j < pts.len() && pts[j].0 < w1 {
            acc += cur_l * (pts[j].0 - cur_t);
            cur_t = pts[j].0;
            cur_l = pts[j].1;
            j += 1;
        }
        acc += cur_l * (w1 - cur_t);
        out.push((acc / dt) as f32);
    }
    out
}

/// Biquad low pass (RBJ cookbook).
struct Biquad {
    b0: f64,
    b1: f64,
    b2: f64,
    a1: f64,
    a2: f64,
    z1: f64,
    z2: f64,
}

impl Biquad {
    fn lowpass(fs: f64, f0: f64, q: f64) -> Self {
        let w = 2.0 * std::f64::consts::PI * f0 / fs;
        let alpha = w.sin() / (2.0 * q);
        let cw = w.cos();
        let a0 = 1.0 + alpha;
        Biquad {
            b0: (1.0 - cw) / 2.0 / a0,
            b1: (1.0 - cw) / a0,
            b2: (1.0 - cw) / 2.0 / a0,
            a1: -2.0 * cw / a0,
            a2: (1.0 - alpha) / a0,
            z1: 0.0,
            z2: 0.0,
        }
    }
    fn run(&mut self, x: f64) -> f64 {
        let y = self.b0 * x + self.z1;
        self.z1 = self.b1 * x - self.a1 * y + self.z2;
        self.z2 = self.b2 * x - self.a2 * y;
        y
    }
}

/// Corner of the high-pass filter in front of the edge detection (Hz).
const HP_HZ: f64 = 100.0;

/// Convert audio to a list of level transition times (seconds), the way the
/// ACI comparator would see it, but more robustly:
/// DC removal, low-pass (if the sample rate allows), adaptive hysteresis
/// (relative to the local amplitude) and zero-crossing interpolation.
pub fn detect_edges(samples: &[f32], sample_rate: u32) -> Vec<f64> {
    let fs = sample_rate as f64;
    let mut out = Vec::new();
    if samples.len() < 2 {
        return out;
    }
    // 1-pole high pass at HP_HZ (was 20 Hz): a mains hum (50 / 60 Hz) of 70 % of the signal
    // level gave a wrong reading with no message (#47); with 100 Hz it reads correctly
    let rc = 1.0 / (2.0 * std::f64::consts::PI * HP_HZ);
    let alpha = rc / (rc + 1.0 / fs);
    let mut lp = if fs >= 16000.0 { Some(Biquad::lowpass(fs, (fs * 0.45).min(6000.0), 0.707)) } else { None };
    let env_decay = (-1.0 / (0.030 * fs)).exp();
    // slow peak follower used as a squelch: when the tape signal stops,
    // background noise stays below 1/4 of the recent signal level long
    // enough for the decoder to see the end of the recording.
    let slow_decay = (-1.0 / (0.5 * fs)).exp();
    let mut slow = 0.0f64;
    let mut prev_x = samples[0] as f64;
    let mut hp = 0.0f64;
    let mut env = 0.0f64;
    let mut state: i8 = 0; // -1 low, +1 high, 0 unknown
    let mut prev_y = 0.0f64;
    let mut last_zc: Option<f64> = None;
    let mut last_emit = f64::NEG_INFINITY;
    for (n, &s) in samples.iter().enumerate() {
        let x = s as f64;
        hp = alpha * (hp + x - prev_x);
        prev_x = x;
        let y = match lp.as_mut() {
            Some(f) => f.run(hp),
            None => hp,
        };
        env = (y.abs()).max(env * env_decay);
        slow = (y.abs()).max(slow * slow_decay);
        let h = (0.12 * env).max(0.25 * slow).max(0.003);
        if n > 0 && (y >= 0.0) != (prev_y >= 0.0) {
            let frac = if prev_y != y { prev_y / (prev_y - y) } else { 0.0 };
            last_zc = Some((n as f64 - 1.0 + frac) / fs);
        }
        prev_y = y;
        let new_state = if y > h {
            1
        } else if y < -h {
            -1
        } else {
            state
        };
        if new_state != state && new_state != 0 {
            if state != 0 {
                let t = match last_zc {
                    Some(z) if z > last_emit => z,
                    _ => n as f64 / fs,
                };
                out.push(t);
                last_emit = t;
            }
            state = new_state;
        }
    }
    out
}

/// Nominal values (seconds) of the ACI ROM output with the default clock
/// model (1.022727 MHz, 4/65 refresh stall). Measured by the
/// `aci_rom_timing` test / `aci_timing` example:
///
/// | element          | CPU cycles | time      |
/// |------------------|-----------:|----------:|
/// | header half      | 592        | ≈ 618 µs (≈ 809 Hz) |
/// | start bit 1st half | 180      | ≈ 188 µs  |
/// | "0" half         | 238        | ≈ 248 µs (≈ 2.01 kHz) |
/// | "1" half         | 473        | ≈ 494 µs (≈ 1.01 kHz) |
pub mod nominal {
    /// Header half period.
    pub const HEADER_HALF: f64 = 0.000_618;
    /// The ROM reader takes a half period shorter than 31 loops of 12 cycles
    /// (≈ 372 cycles ≈ 388 µs) as the start bit.
    pub const START_HALF_MAX: f64 = 0.000_388;
    /// Default full-cycle threshold between "0" (≈ 0.50 ms) and "1" (≈ 0.99 ms).
    pub const BIT_THRESHOLD: f64 = 0.000_742;
    /// Acceptable header half periods (tolerates other encoders such as
    /// c2t, which uses 1 kHz, and tape speed errors).
    pub const HEADER_HALF_MIN: f64 = 0.000_40;
    pub const HEADER_HALF_MAX: f64 = 0.000_90;
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct DecodedSegment {
    pub data: Vec<u8>,
    /// Time of the start bit in the recording (s).
    pub start_secs: f64,
    /// Length of the detected header (s).
    pub header_secs: f64,
    /// Average header half period (s).
    pub header_half: f64,
    /// Bit threshold actually used (s, full cycle).
    pub threshold: f64,
    /// Number of bit cycles that were close to the decision threshold.
    pub weak_bits: usize,
    /// Bits after the last complete byte (ignored).
    pub extra_bits: usize,
}

/// Minimum number of consecutive header half periods to accept a header
/// (≈ 0.2 s; the real ROM needs several seconds, see README).
const MIN_HEADER_HALVES: usize = 300;
/// A run of this many "1" bits inside data is considered a new header
/// (multi-range tapes like `100.1FFW 300.3FFW`).
const NEW_HEADER_ONES: usize = 3000;

/// Remove glitches: a half period much shorter than any legal one is a
/// spike; drop both of its edges.
fn deglitch(edges: &[f64]) -> Vec<f64> {
    let min_half = 0.000_08;
    let mut out: Vec<f64> = Vec::with_capacity(edges.len());
    for &t in edges {
        if let Some(&last) = out.last() {
            if t - last < min_half {
                out.pop();
                continue;
            }
        }
        out.push(t);
    }
    out
}

/// Decode ACI data from edge times. Returns every segment found (one per
/// header). The data carries no address; the caller decides where it goes.
pub fn decode_edges(edges: &[f64]) -> Vec<DecodedSegment> {
    let e = deglitch(edges);
    let halves: Vec<f64> = e.windows(2).map(|w| w[1] - w[0]).collect();
    let n = halves.len();
    let mut segs = Vec::new();
    let mut i = 0usize;
    while i < n {
        // ---- header search ----
        let mut run = 0usize;
        let mut sum = 0.0;
        let mut start: Option<usize> = None;
        while i < n {
            let h = halves[i];
            if run >= MIN_HEADER_HALVES && h < nominal::START_HALF_MAX.min(0.75 * sum / run as f64) {
                start = Some(i);
                break;
            }
            if (nominal::HEADER_HALF_MIN..=nominal::HEADER_HALF_MAX).contains(&h) {
                run += 1;
                sum += h;
            } else {
                run = 0;
                sum = 0.0;
            }
            i += 1;
        }
        let Some(s) = start else { break };
        let header_half = sum / run as f64;
        // ---- data: full cycles after the 2 halves of the start bit ----
        let mut fulls: Vec<f64> = Vec::new();
        let mut k = s + 2;
        let mut ones_run = 0usize;
        let mut new_header_at: Option<usize> = None;
        let gap = 4.0 * nominal::BIT_THRESHOLD;
        while k < n {
            let h1 = halves[k];
            if h1 > gap {
                break;
            }
            if k + 1 >= n || halves[k + 1] > gap {
                // last bit lost its final edge: estimate from first half
                fulls.push(2.0 * h1);
                k += 1;
                break;
            }
            let full = h1 + halves[k + 1];
            fulls.push(full);
            if full > nominal::BIT_THRESHOLD {
                ones_run += 1;
                if ones_run >= NEW_HEADER_ONES {
                    let run_start = fulls.len() - ones_run;
                    new_header_at = Some(run_start);
                    k = k + 2 - 2 * ones_run;
                    break;
                }
            } else {
                ones_run = 0;
            }
            k += 2;
        }
        if let Some(c) = new_header_at {
            fulls.truncate(c.div_ceil(8) * 8);
        }
        // ---- adaptive threshold: midpoint of the two clusters ----
        let mut thr = nominal::BIT_THRESHOLD;
        for _ in 0..3 {
            let (mut s0, mut n0, mut s1, mut n1) = (0.0, 0usize, 0.0, 0usize);
            for &f in &fulls {
                if f > thr {
                    s1 += f;
                    n1 += 1;
                } else {
                    s0 += f;
                    n0 += 1;
                }
            }
            if n0 >= 4 && n1 >= 4 {
                let m0 = s0 / n0 as f64;
                let m1 = s1 / n1 as f64;
                // only trust clusters that look like a 1:2 ratio
                if m1 / m0 > 1.5 && m1 / m0 < 2.6 {
                    thr = 0.5 * (m0 + m1);
                }
            }
        }
        let weak = fulls.iter().filter(|&&f| (f - thr).abs() < 0.15 * thr).count();
        let bits: Vec<bool> = fulls.iter().map(|&f| f > thr).collect();
        let nbytes = bits.len() / 8;
        let data: Vec<u8> = (0..nbytes)
            .map(|b| bits[b * 8..b * 8 + 8].iter().fold(0u8, |acc, &x| (acc << 1) | x as u8))
            .collect();
        if !data.is_empty() {
            segs.push(DecodedSegment {
                data,
                start_secs: e[s],
                header_secs: sum,
                header_half,
                threshold: thr,
                weak_bits: weak,
                extra_bits: bits.len() % 8,
            });
        }
        i = k.max(s + 2);
    }
    segs
}

/// Decode audio samples directly.
pub fn decode_samples(samples: &[f32], sample_rate: u32) -> Vec<DecodedSegment> {
    decode_edges(&detect_edges(samples, sample_rate))
}

/// A cassette in the virtual player, as seen by the ACI comparator.
#[derive(Debug, Clone)]
pub struct TapePlayer {
    pub edges: Vec<f64>,
    /// Emulated time at which the tape started moving (set on first use).
    pub started_at: Option<f64>,
    /// Start automatically on the first read of the tape input.
    pub autostart: bool,
    pub(crate) idx: usize,
    pub(crate) level: bool,
    pub name: String,
}

impl TapePlayer {
    pub fn new(edges: Vec<f64>, name: impl Into<String>) -> Self {
        TapePlayer { edges, started_at: None, autostart: true, idx: 0, level: false, name: name.into() }
    }

    pub fn from_samples(samples: &[f32], rate: u32, name: impl Into<String>) -> Self {
        Self::new(detect_edges(samples, rate), name)
    }

    pub fn duration(&self) -> f64 {
        self.edges.last().copied().unwrap_or(0.0)
    }

    pub fn start(&mut self, now: f64) {
        self.started_at = Some(now);
        self.idx = 0;
        self.level = false;
    }

    pub fn rewind(&mut self) {
        self.started_at = None;
        self.idx = 0;
        self.level = false;
    }

    /// Position on the tape (s) at emulated time `now`.
    pub fn position(&self, now: f64) -> f64 {
        self.started_at.map(|s| (now - s).max(0.0)).unwrap_or(0.0)
    }

    pub fn finished(&self, now: f64) -> bool {
        self.started_at.is_some() && self.position(now) > self.duration() + 0.5
    }

    /// Comparator output at emulated time `now`.
    pub fn level_at(&mut self, now: f64) -> bool {
        if self.started_at.is_none() {
            if !self.autostart {
                return false;
            }
            self.start(now);
        }
        let t = self.position(now);
        while self.idx < self.edges.len() && self.edges[self.idx] <= t {
            self.idx += 1;
            self.level = !self.level;
        }
        self.level
    }
}

#[cfg(test)]
mod range_text_tests {
    use super::*;
    #[test]
    fn aci_range_text_matches_rom_parser() {
        assert_eq!(aci_range_text(0x4A, 0xFF), "004A.00FF");
        assert_eq!(aci_range_text(0x300, 0xFFF), "0300.0FFF");
        assert_eq!(aci_range_text(0x300, 0x31E), "0300.031E");
        assert_eq!(aci_range_text(0xE000, 0xEFFF), "E000.EFFF");
        assert_eq!(aci_range_text(0x0280, 0x03AB), "0280.03AB");
        assert_eq!(aci_range_text(0x1234, 0x1300), "1234.1300");
        assert_eq!(aci_parse_range("4A.FFR"), Some((0x4A, 0x4AFF)));
        assert_eq!(aci_parse_range("4A.00FFR"), Some((0x4A, 0xFF)));
        for s in [0u16, 0x4A, 0x300, 0x1234, 0xE000] {
            for e in [s, s.saturating_add(1), s | 0xFF, s.saturating_add(0x123), 0xFFFF] {
                assert_eq!(aci_parse_range(&aci_range_text(s, e)), Some((s, e)));
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn render_and_detect_are_inverse() {
        let toggles: Vec<f64> = (0..2000).map(|i| i as f64 * 0.000_5 + if i % 3 == 0 { 0.0001 } else { 0.0 }).collect();
        for rate in [22050u32, 44100, 48000] {
            let s = render_toggles(&toggles, &RenderOptions { sample_rate: rate, ..Default::default() });
            let e = detect_edges(&s, rate);
            assert!(e.len() + 2 >= toggles.len() && e.len() <= toggles.len(), "{} vs {}", e.len(), toggles.len());
            // compare spacing in the middle
            let off = e.len() - toggles.len().min(e.len());
            let _ = off;
            let d_e = e[1000] - e[999];
            let d_t = toggles[1000 + (toggles.len() - e.len())] - toggles[999 + (toggles.len() - e.len())];
            assert!((d_e - d_t).abs() < 0.000_03, "rate {rate}: {d_e} vs {d_t}");
        }
    }

    /// 4096 bytes of tape with a mains hum of `hum` times the signal level added (#47).
    fn hummed(hum: f64, freq: f64, rate: u32) -> (Vec<u8>, Vec<DecodedSegment>) {
        let mut x = 12345u32;
        let data: Vec<u8> = (0..4096)
            .map(|_| {
                x = x.wrapping_mul(1664525).wrapping_add(1013904223);
                (x >> 24) as u8
            })
            .collect();
        let toggles = rom_write_toggles(&[(0x300, &data)], Timing::default()).unwrap();
        let o = RenderOptions { sample_rate: rate, ..Default::default() };
        let mut s = render_toggles(&toggles, &o);
        for (n, v) in s.iter_mut().enumerate() {
            *v += (hum * o.amplitude as f64 * (2.0 * std::f64::consts::PI * freq * n as f64 / rate as f64).sin()) as f32;
        }
        (data, decode_samples(&s, rate))
    }

    #[test]
    fn mains_hum_does_not_break_the_reading() {
        for (hum, freq, rate) in [(0.0, 50.0, 44100), (0.0, 50.0, 22050), (0.0, 50.0, 48000), (0.0, 50.0, 11025), (0.7, 50.0, 22050), (0.5, 50.0, 44100), (0.7, 50.0, 44100), (0.7, 100.0, 44100), (1.0, 50.0, 44100), (0.7, 60.0, 48000)] {
            let (data, segs) = hummed(hum, freq, rate);
            let ok = segs.first().is_some_and(|g| g.data.len() >= data.len() && g.data[..data.len()] == data[..]);
            assert!(ok, "hum {hum} at {freq} Hz: {:?}", segs.first().map(|g| (g.data.len(), g.data.iter().zip(&data).filter(|(a, b)| a != b).count())));
        }
    }
}
